                M_030_bb -= temp + temp.transpose(2, 3, 0, 1)
                temp = lib.einsum('ibac,ljcb,jd->idla',
                                    v_ceee_bbbb,
                                    t1_ccee_bbbb,
                                    t1_ce_bb, optimize=einsum_type)
                M_030_bb -= 1/2 * (temp + temp.transpose(2, 3, 0, 1))
