                M_030_bb += temp + temp.transpose(2, 3, 0, 1)
                temp = lib.einsum('ibce,ljbe,jc->il',
                                    v_ceee_bbbb,
                                    t1_ccee_bbbb,
                                    t1_ce_bb, optimize=einsum_type)
                M_030_bb[:, vir_list_b, :, vir_list_b] -= temp + temp.T
                temp = lib.einsum('jbce,ijbe,lc->il',
                                    v_ceee_bbbb,
                                    t1_ccee_bbbb,
                                    t1_ce_bb, optimize=einsum_type)
                M_030_bb[:, vir_list_b, :, vir_list_b] += temp + temp.T
