    temp += 1/2 * lib.einsum('iA,ja,ikBb,jkab->AB', L_aa, R_aa, t2_1_ab, t2_1_ab, optimize = True)
    temp += 1/2 * lib.einsum('iA,ja,ikBb,kjba->AB', L_aa, R_bb, t2_1_a, t2_1_ab, optimize = True)
    temp -= lib.einsum('ia,jb,ikBa,kjAb->AB', L_aa, R_bb, t2_1_a, t2_1_ab, optimize = True)
