    rdm1_a[nocc_a:, nocc_a:] += temp + temp.T
    rdm1_a[nocc_a:, nocc_a:] += 1/2 * lib.einsum('ia,ia,jkAb,jkBb->AB', L_aa, R_aa, t2_1_a, t2_1_a, optimize = True)
    rdm1_a[nocc_a:, nocc_a:] -= 1/2 * lib.einsum('ia,ib,jkBa,jkAb->AB', L_aa, R_aa, t2_1_a, t2_1_a, optimize = True)
    rdm1_a[nocc_a:, nocc_a:] -= lib.einsum('ia,ja,ikBb,jkAb->AB', L_aa, R_aa, t2_1_a, t2_1_a, optimize = True)
    rdm1_a[nocc_a:, nocc_a:] += lib.einsum('ia,jb,ikBa,jkAb->AB', L_aa, R_aa, t2_1_a, t2_1_a, optimize = True)
    rdm1_a[nocc_a:, nocc_a:] += lib.einsum('ia,ia,jkAb,jkBb->AB', L_aa, R_aa, t2_1_ab, t2_1_ab, optimize = True)
    rdm1_a[nocc_a:, nocc_a:] -= lib.einsum('ia,ja,ikBb,jkAb->AB', L_aa, R_aa, t2_1_ab, t2_1_ab, optimize = True)
    rdm1_a[nocc_a:, nocc_a:] += 1/2 * lib.einsum('ia,ia,jkAb,jkBb->AB', L_bb, R_bb, t2_1_a, t2_1_a, optimize = True)
    rdm1_a[nocc_a:, nocc_a:] += lib.einsum('ia,ia,jkAb,jkBb->AB', L_bb, R_bb, t2_1_ab, t2_1_ab, optimize = True)
    rdm1_a[nocc_a:, nocc_a:] -= lib.einsum('ia,ib,jkBa,jkAb->AB', L_bb, R_bb, t2_1_ab, t2_1_ab, optimize = True)
    rdm1_a[nocc_a:, nocc_a:] -= lib.einsum('ia,ja,kiBb,kjAb->AB', L_bb, R_bb, t2_1_ab, t2_1_ab, optimize = True)
    rdm1_a[nocc_a:, nocc_a:] += lib.einsum('ia,jb,kiBa,kjAb->AB', L_bb, R_bb, t2_1_ab, t2_1_ab, optimize = True)
    rdm1_b[nocc_b:, nocc_b:] += lib.einsum('ia,ia,jkbA,jkbB->AB', L_aa, R_aa, t2_1_ab, t2_1_ab, optimize = True)
    rdm1_b[nocc_b:, nocc_b:] -= lib.einsum('ia,ib,jkaB,jkbA->AB', L_aa, R_aa, t2_1_ab, t2_1_ab, optimize = True)
    rdm1_b[nocc_b:, nocc_b:] -= lib.einsum('ia,ja,ikbB,jkbA->AB', L_aa, R_aa, t2_1_ab, t2_1_ab, optimize = True)
    rdm1_b[nocc_b:, nocc_b:] += lib.einsum('ia,jb,ikaB,jkbA->AB', L_aa, R_aa, t2_1_ab, t2_1_ab, optimize = True)
    rdm1_b[nocc_b:, nocc_b:] += 1/2 * lib.einsum('ia,ia,jkAb,jkBb->AB', L_aa, R_aa, t2_1_b, t2_1_b, optimize = True)
    temp = np.zeros((nvir_b, nvir_b))
