    temp -= 1/2 * lib.einsum('iA,ia,jkba,jkbB->AB', L_bb, R_bb, t2_1_ab, t2_1_ab, optimize = True)
    temp += 1/2 * lib.einsum('iA,ja,kibB,kjba->AB', L_bb, R_bb, t2_1_ab, t2_1_ab, optimize = True)
    temp -= 1/4 * lib.einsum('iA,ia,jkab,jkBb->AB', L_bb, R_bb, t2_1_b, t2_1_b, optimize = True)
