    rdm1_b[nocc_b:, nocc_b:] += temp + temp.T
    rdm1_b[nocc_b:, nocc_b:] += lib.einsum('ia,ia,jkbA,jkbB->AB', L_bb, R_bb, t2_1_ab, t2_1_ab, optimize = True)
    rdm1_b[nocc_b:, nocc_b:] -= lib.einsum('ia,ja,kibB,kjbA->AB', L_bb, R_bb, t2_1_ab, t2_1_ab, optimize = True)
    rdm1_b[nocc_b:, nocc_b:] += 1/2 * lib.einsum('ia,ia,jkAb,jkBb->AB', L_bb, R_bb, t2_1_b, t2_1_b, optimize = True)
    rdm1_b[nocc_b:, nocc_b:] -= 1/2 * lib.einsum('ia,ib,jkBa,jkAb->AB', L_bb, R_bb, t2_1_b, t2_1_b, optimize = True)
    rdm1_b[nocc_b:, nocc_b:] -= lib.einsum('ia,ja,ikBb,jkAb->AB', L_bb, R_bb, t2_1_b, t2_1_b, optimize = True)
    rdm1_b[nocc_b:, nocc_b:] += lib.einsum('ia,jb,ikBa,jkAb->AB', L_bb, R_bb, t2_1_b, t2_1_b, optimize = True)
    rdm1_a[nocc_a:, nocc_a:] += 1/2 * lib.einsum('ijAa,ijBa->AB', L_aaaa_u, R_aaaa_u, optimize = True)
    rdm1_a[nocc_a:, nocc_a:] += lib.einsum('ijAa,ijBa->AB', L_ab, R_ab, optimize = True)
