        rdm1_a[nocc_a:, nocc_a:] -= 1/2 * lib.einsum('ia,iB,ja,jA->AB', L_aa, R_aa, t1_1_a, t1_1_a, optimize = True)
        rdm1_a[nocc_a:, nocc_a:] += lib.einsum('ia,ia,jA,jB->AB', L_aa, R_aa, t1_1_a, t1_1_a, optimize = True)
