        rdm1_a[nocc_a:, nocc_a:] += lib.einsum('ia,ia,jA,jB->AB', L_bb, R_bb, t1_1_a, t1_1_a, optimize = True)
        rdm1_b[nocc_b:, nocc_b:] += lib.einsum('ia,ia,jA,jB->AB', L_aa, R_aa, t1_1_b, t1_1_b, optimize = True)
