        rdm1_b[nocc_b:, nocc_b:] -= 1/2 * lib.einsum('ia,iB,ja,jA->AB', L_bb, R_bb, t1_1_b, t1_1_b, optimize = True)
        rdm1_b[nocc_b:, nocc_b:] += lib.einsum('ia,ia,jA,jB->AB', L_bb, R_bb, t1_1_b, t1_1_b, optimize = True)
        rdm1_b[nocc_b:, nocc_b:] -= lib.einsum('ia,ja,iB,jA->AB', L_bb, R_bb, t1_1_b, t1_1_b, optimize = True)
