        rdm1_b[:nocc_b, nocc_b:] += lib.einsum('ia,ia,IA->IA', L_aa, R_aa, t1_1_b, optimize = True)
        rdm1_b[:nocc_b, nocc_b:] -= lib.einsum('ia,Ia,iA->IA', L_bb, R_bb, t1_1_b, optimize = True)
