        temp += lib.einsum('ia,ib,Ijac,Jjbc->IJ', L_aa, R_aa, t2_1_ab, t2_2_ab, optimize = True)
        temp -= 1/2 * lib.einsum('Ja,ib,Ijac,jicb->IJ', L_aa, R_bb, t2_1_a, t2_2_ab, optimize = True)
