        temp -= 1/2 * lib.einsum('Ja,ib,jicb,Ijac->IJ', L_aa, R_bb, t2_1_ab, t2_2_a, optimize = True)
        temp += lib.einsum('ia,jb,Jjcb,Iiac->IJ', L_aa, R_bb, t2_1_ab, t2_2_a, optimize = True)
