        temp -= 1/2 * lib.einsum('ia,ia,Ijbc,Jjbc->IJ', L_bb, R_bb, t2_1_b, t2_2_b, optimize = True)
        temp += lib.einsum('ia,ib,Ijac,Jjbc->IJ', L_bb, R_bb, t2_1_b, t2_2_b, optimize = True)
        temp += 1/2 * lib.einsum('ia,ja,Iibc,Jjbc->IJ', L_bb, R_bb, t2_1_b, t2_2_b, optimize = True)
